 [TestMethod]public Task VisualScopesCropContextAndNodeThumbnailsInstantiate()=>RunSta(async()=>{
  EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"r53-visual-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var input=Path.Combine(root,"input.png");StudioQuickExport.Encode(BitmapSource.Create(120,80,96,96,PixelFormats.Rgb24,null,Enumerable.Range(0,120*80*3).Select(i=>(byte)(i%230)).ToArray(),360),input,input,StudioExportFormat.Png);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root));await vm.LoadTargetAsync(input);vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure"),.3);await vm.Editor.ApplyCommand.ExecuteAsync(null);var view=new RAWSelectionAssistant.Views.PhotoGradePageView{DataContext=vm};view.Measure(new Size(1920,1080));view.Arrange(new Rect(0,0,1920,1080));view.UpdateLayout();await vm.AnalysisWork;await Task.Delay(250);view.UpdateLayout();Assert.IsNotNull(view.FindName("CropOverlay"));Assert.IsTrue(view.ExecuteR53PointerShortcut(System.Windows.Input.Key.C));var thumbs=Descendants(view).OfType<RAWSelectionAssistant.Views.StudioLayerThumbnail>().ToArray();Assert.IsTrue(thumbs.Length>=2,"Real layer effect and mask thumbnail controls");Assert.IsTrue(thumbs.Any(t=>t.RenderedImage is not null),"Thumbnail asynchronously publishes actual bitmap");var output=Environment.GetEnvironmentVariable("KITAO_R53_VISUAL");if(output is not null){Directory.CreateDirectory(output);var image=new RenderTargetBitmap(1920,1080,96,96,PixelFormats.Pbgra32);image.Render(view);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var f=File.Create(Path.Combine(output,"darkroom-offscreen.png"));encoder.Save(f);}view.DataContext=null;}finally{Directory.Delete(root,true);}
 });
 [TestMethod]public Task AuthorizedRawFastFineErrorProgressiveCompareAndSceneExposure()=>RunSta(async()=>{
  var output=Environment.GetEnvironmentVariable("KITAO_R53_REAL_INTERACTION");if(output is null){Assert.Inconclusive("Explicit named RAW output required");return;}EnsureTestApplication();Directory.CreateDirectory(output);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(output));await vm.LoadTargetAsync("D:/AI AGENT/PixelTart-TestAssets/CompanyRAW/TNAN8886.CR3");await vm.CreateProfessionalRawCommand.ExecuteAsync(null);Assert.IsTrue(vm.RawLocalEditing,vm.StatusText);var target=vm.ActiveTarget!;await vm.RawBaseWarmWork;var parameter=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure");vm.Editor.SetToolParameter(parameter,.4);vm.Editor.AddMaskStroke(new([new(.2,.3),new(.7,.6)],.08,.6,.7,1));await vm.RawLocalPreviewWork;var d=target.RawDefinition!;var master=target.LinearRawMaster!;RawLocalProfile.Reset();var timer=Stopwatch.StartNew();using var basis=ProfessionalRawLocalRenderer.FastBase(master,d);var baseMs=timer.Elapsed.TotalMilliseconds;timer.Restart();using var fast=ProfessionalRawLocalRenderer.Fast(master,d,basis);var fastMs=timer.Elapsed.TotalMilliseconds;timer.Restart();using var fine=ProfessionalRawPipeline.RenderPreview(master,d,800);var fineMs=timer.Elapsed.TotalMilliseconds;var errors=fast.Rgb32.ToArray().Zip(fine.Rgb32.ToArray(),(a,b)=>Math.Abs(a-b)*255).Order().ToArray();double mean=errors.Average(),p95=errors[(int)(errors.Length*.95)],maximum=errors[^1];Assert.IsTrue(mean<=1.5&&p95<=4&&maximum<=32,"Frozen preimplementation error budget");
  var quality=new List<object>();var qualityTimes=new List<(double Ms,string Value)>();var clock=Stopwatch.StartNew();vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.RawPreviewQuality)){quality.Add(new{ms=clock.Elapsed.TotalMilliseconds,value=vm.RawPreviewQuality});qualityTimes.Add((clock.Elapsed.TotalMilliseconds,vm.RawPreviewQuality));}};for(int i=0;i<20;i++){vm.Editor.SelectedLayerOpacity=.3+i*.02;await Task.Delay(20);}await vm.RawLocalPreviewWork;Assert.AreEqual("精细",vm.RawPreviewQuality);Assert.IsTrue(qualityTimes.First(x=>x.Value.StartsWith("快速")).Ms<800,"Predeclared warm interactive first update budget");Assert.IsTrue(qualityTimes.Count(x=>x.Value.StartsWith("快速"))>=2,"Effective intermediate updates during input");
  var baseline=Pixels(vm.Editor.MatchedImage!);using var beforeScene=ProfessionalRawPipeline.RenderPreview(master,target.RawDefinition!,800);vm.SceneLocalExposureEv=-1.5;vm.BindSceneExposureMask();await vm.RawLocalPreviewWork;using var afterScene=ProfessionalRawPipeline.RenderPreview(master,target.RawDefinition!,800);var sceneDelta=beforeScene.Rgb32.ToArray().Zip(afterScene.Rgb32.ToArray(),(a,b)=>Math.Abs(a-b)).ToArray();var scene=target.RawDefinition!.SceneExposure;Assert.IsNotNull(scene);Assert.IsFalse(baseline.SequenceEqual(Pixels(vm.Editor.MatchedImage!)));var project=Path.Combine(output,"scene.ptstudio.json");await vm.SaveSessionAsync(project);var originalVariant=target.ActiveEditVersionId;var frozen=JsonSerializer.Serialize(target.RawDefinition);await vm.CreateR53VariantAsync(false);vm.Editor.SelectedLayerOpacity=.8;await vm.RawLocalPreviewWork;await vm.CreateR53VariantAsync(false);vm.Editor.SelectedLayerOpacity=.4;await vm.RawLocalPreviewWork;await vm.CreateR53VariantAsync(false);vm.Editor.SelectedLayerOpacity=.6;await vm.RawLocalPreviewWork;var ids=vm.R53Variants.Where(v=>v.RawDefinition is not null).Take(4).Select(v=>v.Id).ToArray();double? first=null;int notifications=0;clock.Restart();vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.R53CompareFrames)&&vm.R53CompareFrames.Count>0){first??=clock.Elapsed.TotalMilliseconds;notifications++;}};await vm.PrepareR53VariantComparisonAsync(ids);var allMs=clock.Elapsed.TotalMilliseconds;Assert.IsTrue(notifications>=ids.Length);Assert.IsTrue(first<allMs);clock.Restart();await vm.PrepareR53VariantComparisonAsync(ids);var hotAllMs=clock.Elapsed.TotalMilliseconds;Assert.AreEqual(ids.Length,vm.R53CompareFrames.Count);var cancelTask=vm.PrepareR53VariantComparisonAsync(ids);vm.CloseR53VariantComparison();await cancelTask;Assert.IsEmpty(vm.R53CompareFrames);
  await vm.SwitchEditVersionAsync(originalVariant!.Value);await vm.SaveSessionAsync(project);Assert.AreEqual(frozen,JsonSerializer.Serialize(target.RawDefinition));var exported=Path.Combine(output,"scene-export.tif");var exportWatch=Stopwatch.StartNew();await ProfessionalRawExport.WriteAsync(master,target.RawDefinition!,exported,StudioExportFormat.Tiff);var inspection=ProfessionalRawExport.Inspect(exported,master,target.RawDefinition!,StudioExportFormat.Tiff);Assert.AreEqual(0,inspection.MaximumError);using var reopened=new ReferenceColorWorkspaceViewModel(new Dialogs(Path.Combine(output,"reopened")));await reopened.LoadSessionAsync(project);Assert.AreEqual(frozen,JsonSerializer.Serialize(reopened.ActiveTarget!.RawDefinition));
  var cropView=new RAWSelectionAssistant.Views.PhotoGradePageView{DataContext=reopened};cropView.Measure(new Size(1920,1080));cropView.Arrange(new Rect(0,0,1920,1080));cropView.UpdateLayout();Assert.IsTrue(cropView.ExecuteR53PointerShortcut(System.Windows.Input.Key.C));var viewport=(RAWSelectionAssistant.Views.ColorStudioImageViewport)cropView.FindName("PhotoViewport");var rect=viewport.State.ImageRect(new Rect(viewport.RenderSize));var cropDown=typeof(RAWSelectionAssistant.Views.PhotoGradePageView).GetMethod("CropDown",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;var cropMove=typeof(RAWSelectionAssistant.Views.PhotoGradePageView).GetMethod("CropMove",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;var cropUp=typeof(RAWSelectionAssistant.Views.PhotoGradePageView).GetMethod("CropUp",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;cropDown.Invoke(cropView,new object[]{new Point(rect.Left+rect.Width*.1,rect.Top+rect.Height*.1)});cropMove.Invoke(cropView,new object[]{new Point(rect.Left+rect.Width*.8,rect.Top+rect.Height*.85)});cropUp.Invoke(cropView,null);Assert.IsNotNull(reopened.ActiveTarget.RawDefinition!.Geometry,"Actual crop context drag commits geometry");await reopened.PhotoGradeUndoCommand.ExecuteAsync(null);await reopened.RawLocalPreviewWork;Assert.AreEqual(frozen,JsonSerializer.Serialize(reopened.ActiveTarget.RawDefinition));cropView.DataContext=null;
  File.WriteAllText(Path.Combine(output,"REAL_INTERACTION.json"),JsonSerializer.Serialize(new{baseMs,fastMs,fineMs,sceneExportMs=exportWatch.Elapsed.TotalMilliseconds,mean,p95,maximum,quality,compareCount=ids.Length,compareFirstMs=first,compareAllMs=allMs,compareHotAllMs=hotAllMs,notifications,sceneDefinition=frozen,profile=RawLocalProfile.Snapshot(),sceneMeanAbsolute=sceneDelta.Average(),sceneMaximum=sceneDelta.Max(),peakWorkingSetBytes=Process.GetCurrentProcess().PeakWorkingSet64,ledger=StudioGlobalResources.AccountedBytes,CalibrationEligible=false,scope="Real20MP Canon, same frozen state fast approximation/fine; not physical pointer or color calibration"},new JsonSerializerOptions{WriteIndented=true}));
 });
 static IEnumerable<DependencyObject> Descendants(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);yield return child;foreach(var descendant in Descendants(child))yield return descendant;}}
 static byte[] Pixels(BitmapSource s){var r=new FormatConvertedBitmap(s,PixelFormats.Rgb24,null,0);var b=new byte[r.PixelWidth*r.PixelHeight*3];r.CopyPixels(b,r.PixelWidth*3,0);return b;}
 sealed class Dialogs(string root):IDialogService{public IReadOnlyList<string> ChooseFiles(string a,string b,bool c)=>[];public string? ChooseFolder(string a,string? b=null)=>root;public string? ChooseSaveFile(string a,string b,string c,string? d=null)=>null;public bool Confirm(string a,string b)=>true;public void ShowInfo(string a){}public void ShowError(string a){}public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string> ids)=>ids;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RAWSelectionAssistant.Core.Models.RawFileEntry? ChooseRawCandidate(IReadOnlyList<RAWSelectionAssistant.Core.Models.RawFileEntry> x)=>null;public bool ShowMediaDetails(RAWSelectionAssistant.Core.Models.MediaSelectionItem x,bool y)=>false;public void RevealFile(string p){}}
